P=[x for x in P if x[0] not in GEN]+[x for x in P if x[0] in GEN]
s = src
# JSON-LD FAQ
for qe,qs,ae,as_ in FAQ:
    for a,b in ((f'"name": "{qe}"', f'"name": "{qs}"'), (f'"text": "{ae}"', f'"text": "{as_}"')):
        if a not in s: sys.exit("MISSING LD: "+a[:80])
        s = s.replace(a,b)
for a,b in P:
    n = s.count(a)
    if n == 0: sys.exit("MISSING: "+a[:80])
